(def probe-source
  "Exact historical MCP forms. Load the recorded base probe and classloader first;
   evaluate this source in user in the isolated development JVM, never default."
  "; Evaluated candidate and canonical regression, not a landed production change.\n(in-ns 'seon.turn)\n\n(defn- row-tx\n  \"Validate and exact-upsert one reader-produced durable declaration.\"\n  [db request row]\n  (if-let [deleted-identities (:seon.program/delete-identities row)]\n    (let [schema-keys\n          (into #{}\n                (keep (fn [[identity-attribute identity-value]]\n                        (when (= :seon.schema/key identity-attribute)\n                          identity-value)))\n                deleted-identities)\n          current-projection\n          (when (seq schema-keys)\n            (schema/projection-from-database\n             db\n             (or (db/carried-projection db)\n                 (throw (ex-info \"Declaration database has no carried projection\"\n                                 (db/projection-fallback 'seon.turn/row-tx))))))\n          candidate-projection\n          (reduce schema/projection-without-schema\n                  current-projection\n                  (sort schema-keys))\n          _ (when (seq schema-keys)\n              (assert-schema-data-unused!\n               db current-projection schema-keys))\n          schema-tx\n          (if (seq schema-keys)\n            (schema-attribute-change-tx\n             db current-projection candidate-projection)\n            [])\n          declarations\n          (into []\n                (keep (fn [[identity-attribute identity-value]]\n                        (when-let [declaration\n                                   (db/pull db '[*]\n                                           [identity-attribute identity-value])]\n                          [identity-attribute identity-value declaration])))\n                deleted-identities)]\n      (into schema-tx\n            (mapcat\n             (fn [[identity-attribute identity-value declaration]]\n               (map (fn [attribute]\n                      [:db.fn/retractAttribute (:db/id declaration) attribute])\n                    (program/changed-attributes\n                     declaration {identity-attribute identity-value}))))\n            declarations))\n    (let [row (or (program/declaration-row row :all :agent)\n                  (refuse! `receipt-settle-call\n                           ::row-not-admitted request))\n          [identity identity-value] (program/row-identity row)\n          namespace-ref (or (:seon.fn/ns row)\n                            (:seon.test/ns row))\n          existing (when identity (db/pull db '[*] [identity identity-value]))\n          subject-symbol\n          (or (second (:seon.test/subject row))\n              (:seon.test/pending-subject row))\n          row\n          (if (and (= :seon.test/sym identity) subject-symbol)\n            (if (:db/id (db/pull db [:db/id]\n                                 [:seon.fn/sym subject-symbol]))\n              (-> row\n                  (dissoc :seon.test/pending-subject)\n                  (assoc :seon.test/subject\n                         [:seon.fn/sym subject-symbol]))\n              (-> row\n                  (dissoc :seon.test/subject)\n                  (assoc :seon.test/pending-subject subject-symbol)))\n            row)]\n      (when (and namespace-ref\n                 (not (:db/id (db/pull db [:db/id] namespace-ref))))\n        (refuse! `receipt-settle-call ::program-namespace-missing request))\n      (let [current-projection\n            (when (or (= :seon.schema/key identity)\n                      (and (= :seon.fn/sym identity)\n                           (:seon.fn/spec row)))\n              ;; Earlier declarations in this same transaction are already\n              ;; facts in db, but are absent from its entering projection.\n              ;; Validate against the writer's current value, reusing compiled\n              ;; declarations through the schema owner's existing derivation.\n              (schema/projection-from-database\n               db\n               (or (db/carried-projection db)\n                   (throw (ex-info \"Declaration database has no carried projection\"\n                                   (db/projection-fallback 'seon.turn/row-tx))))))\n            schema-redefinition?\n            (and (= identity :seon.schema/key)\n                 existing\n                 (not= (:seon.schema/form existing)\n                       (:seon.schema/form row)))\n            ;; ONE decision path owns \"may this declaration change\". The\n            ;; concurrency question — did the installed row diverge from the\n            ;; basis this run opened on — is measured identically for every\n            ;; declaration family. What differs is only what a legal change\n            ;; then costs, and for a schema key that cost is answered by the\n            ;; usage guard, which names the attributes current data blocks on.\n            concurrent-declaration?\n            (and (#{:seon.fn/sym :seon.schema/key} identity)\n                 existing\n                 (not= (declared-content db existing)\n                       (declared-content db row))\n                 (declaration-diverged-since-open?\n                  db request identity identity-value existing))\n            _ (when concurrent-declaration?\n                (refuse! `receipt-settle-call\n                         ::program-row-changed-after-open request))\n            _ (when schema-redefinition?\n                (assert-schema-data-unused!\n                 db current-projection #{identity-value}))\n            candidate-projection\n            (case identity\n              :seon.schema/key\n              (schema/projection-with-schema\n               current-projection identity-value\n               (edn/read-string (:seon.schema/form row))\n               {:seon.schema.admission/source :agent})\n\n              :seon.fn/sym\n              (when (:seon.fn/spec row)\n              (schema/projection-with-function-contract\n               current-projection (symbol identity-value)\n               (edn/read-string (:seon.fn/spec row))\n               {:seon.schema.admission/source :agent}))\n\n              nil)\n            ; Decide target existence at the writer, including earlier batch rows.\n            unresolved-calls\n            (into #{}\n                  (comp (filter #(and (vector? %) (= :seon.fn/sym (first %))))\n                        (remove #(or (= [identity identity-value] %)\n                                     (:db/id (db/pull db [:db/id] %))))\n                        (map second))\n                  (:seon.fn/calls row))\n            pending-calls (into (set (:seon.fn/pending-calls row)) unresolved-calls)\n            resolved-pending\n            (into #{} (filter #(or (= [identity identity-value] [:seon.fn/sym %])\n                                  (:db/id (db/pull db [:db/id] [:seon.fn/sym %]))))\n                  pending-calls)\n            row (cond-> (dissoc row :seon.fn/pending-calls)\n                  (seq pending-calls)\n                  (assoc :seon.fn/pending-calls (into #{} (remove resolved-pending) pending-calls))\n                  (or (seq (:seon.fn/calls row)) (seq resolved-pending))\n                  (assoc :seon.fn/calls\n                         (into (into #{} (remove #(and (vector? %)\n                                                      (unresolved-calls (second %))))\n                                     (:seon.fn/calls row))\n                               (map #(vector :seon.fn/sym %)) resolved-pending)))\n            relation-row (select-keys row program-relation-attributes)\n            base-row (apply dissoc row program-relation-attributes)\n            schema-declarations\n            (if (= identity :seon.schema/key)\n              (if schema-redefinition?\n                (schema-attribute-change-tx\n                 db current-projection candidate-projection)\n                (let [current-attributes\n                      (schema.datahike/database-attributes-in\n                       current-projection)\n                      candidate-attributes\n                      (schema.datahike/database-attributes-in\n                       candidate-projection)\n                      required\n                      (into []\n                            (comp\n                             (remove (set current-attributes))\n                             (remove #(contains? (:schema db) %)))\n                            (sort candidate-attributes))]\n                  (schema.datahike/malli->datahike-schema-in\n                   candidate-projection required)))\n              [])]\n        (into schema-declarations\n              (concat\n               (cond\n                 (nil? existing)\n                 [(assoc base-row :db/id\n                         (str (name identity) \":\" identity-value))]\n\n                 (= (declared-content db existing) (declared-content db row))\n                 []\n\n                 :else\n                 (program/exact-replacement-tx existing base-row))\n               (relation-assertions [identity identity-value]\n                                    relation-row)\n               (pending-relation-resolution-tx\n                db identity identity-value existing)))))))\n\n(in-ns 'seon.cluster.turn-test)\n\n(deftest schema-deletion-sees-earlier-declarations-in-the-same-transaction\n  (doseq [dependent? [false true]]\n    (test-support/with-database\n     (fn [connection]\n       (let [base-key :turn-schema-batch/value\n             dependent-key :turn-schema-batch/dependent\n             declaration {:seon.schema/key base-key\n                          :seon.schema/form \"[:int {:seon.db/index true}]\"}\n             transaction\n             (cond-> [[:db.fn/call #'turn/row-tx {} declaration]]\n               dependent?\n               (conj [:db.fn/call #'turn/row-tx {}\n                      {:seon.schema/key dependent-key\n                       :seon.schema/form (pr-str base-key)}])\n               true\n               (conj [:db.fn/call #'turn/row-tx {}\n                      {:seon.program/delete-identities\n                       [[:seon.schema/key base-key]]}]))\n             result (db/transact! connection transaction)\n             database (db/db connection)]\n         (if dependent?\n           (do\n             (is (= :seon.db/rejected (:seon.error/kind result)))\n             (is (str/includes? (pr-str result) \"schema-in-use\")\n                 \"a dependency declared earlier in this transaction blocks deletion\")\n             (is (nil? (db/pull database [:db/id] [:seon.schema/key base-key]))\n                 \"the refused transaction rolls back its earlier declarations\"))\n           (do\n             (is (some? (:db-after result)) (pr-str result))\n             (is (stable-program-identity-row?\n                  (db/pull database '[*] [:seon.schema/key base-key])\n                  :seon.schema/key base-key nil))\n             (is (not (contains? (:schema database) base-key)))\n             (is (not (contains? (:seon.schema.projection/forms\n                                  (schema/projection-from-database database))\n                                base-key))))))))))\n\n(in-ns 'user)\n(def reds19-writer-observations (atom []))\n(defn reds19-prepare []\n  (binding [*ns* *ns*]\n    (load-file \"/Users/sean/src/seon/tmp/turn-test-reds19/schema-production.clj\"))\n  (let [original @(ns-resolve 'seon.turn 'schema-attribute-change-tx)]\n    (alter-var-root\n     (ns-resolve 'seon.turn 'schema-attribute-change-tx)\n     (constantly\n      (fn [database current candidate]\n        (let [result (original database current candidate)]\n          (swap! reds19-writer-observations conj\n                 {:cache-context (:cache-context database)\n                  :queried (get-in (seon.schema/projection-from-database database current)\n                                   [:seon.schema.projection/forms :turn-schema-batch/value])\n                  :uncached (binding [datahike.query/*query-result-cache?* false]\n                              (get-in (seon.schema/projection-from-database database current)\n                                      [:seon.schema.projection/forms :turn-schema-batch/value]))\n                  :current (get-in current [:seon.schema.projection/forms :turn-schema-batch/value])\n                  :candidate (get-in candidate [:seon.schema.projection/forms :turn-schema-batch/value])\n                  :stored (seon.db/pull database [:seon.schema/form] [:seon.schema/key :turn-schema-batch/value])\n                  :transaction result})\n          result))))))\n")

(comment
  (binding [*ns* (find-ns 'user)]
    (load-string probe-source)))
